import { NextResponse } from 'next/server';
import crypto from 'crypto';

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    const sessionId = searchParams.get('session_id');

    if (!sessionId) {
        return NextResponse.json({ error: 'Missing session_id' }, { status: 400 });
    }

    // Generate a random 32-byte nonce
    const nonce = crypto.randomBytes(32).toString('hex');

    // In a real app, we would store this nonce against the session_id in the DB 
    // with an expiry to prevent replay attacks.
    // await redis.set(`nonce:${sessionId}`, nonce, 'EX', 60);

    return NextResponse.json({ nonce });
}

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export async function POST(request: Request) {
    try {
        const body = await request.json();
        const { publicKey, name } = body;

        console.log('[API] Registering Device:', { name, publicKey: publicKey?.substring(0, 20) + '...' });

        if (!publicKey) {
            return NextResponse.json({ error: 'Missing public key' }, { status: 400 });
        }

        // Check if device exists
        const { data: existing } = await supabase
            .from('devices')
            .select('id')
            .eq('public_key', publicKey)
            .single();

        if (existing) {
            return NextResponse.json({
                success: true,
                message: 'Device already registered',
                id: existing.id
            });
        }

        // Insert new device
        const { data, error } = await supabase
            .from('devices')
            .insert([
                {
                    public_key: publicKey,
                    name: name || 'Unnamed Kiosk',
                    last_active: new Date().toISOString()
                }
            ])
            .select()
            .single();

        if (error) {
            console.error('[API] Supabase Insert Error:', error);
            return NextResponse.json({ error: error.message }, { status: 500 });
        }

        return NextResponse.json({ success: true, device: data });

    } catch (e) {
        console.error('[API] Server Error:', e);
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
    }
}

import { createClient } from '@supabase/supabase-js';
import { NextResponse } from 'next/server';

export async function POST(request: Request) {
    try {
        // Initialize Supabase Client
        const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
        const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
        const supabase = createClient(supabaseUrl, supabaseKey);

        // Get Token from Header
        const authHeader = request.headers.get('Authorization');
        if (!authHeader) {
            return NextResponse.json({ error: 'Missing Authorization Header' }, { status: 401 });
        }
        const token = authHeader.replace('Bearer ', '');

        // Verify User
        const { data: { user }, error: authError } = await supabase.auth.getUser(token);

        if (authError || !user) {
            return NextResponse.json({ error: 'Unauthorized: Invalid Token' }, { status: 401 });
        }

        // Perform Update in context of user
        const authenticatedSupabase = createClient(supabaseUrl, supabaseKey, {
            global: { headers: { Authorization: `Bearer ${token}` } }
        });

        const { error } = await authenticatedSupabase
            .from('users')
            .update({
                face_verified: true,
                updated_at: new Date().toISOString()
            })
            .eq('id', user.id);

        if (error) {
            console.error('Update Face Verified Error:', error);
            return NextResponse.json({ error: error.message }, { status: 500 });
        }

        return NextResponse.json({ success: true });

    } catch (error) {
        console.error('API Error:', error);
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
    }
}

import { NextResponse } from 'next/server';
