    useEffect(() => {
        const handleAuthCallback = async () => {
            // 1. Get User Session (handled by Supabase automatically on redirect)
            const { data: { user } } = await supabase.auth.getUser();

            if (user) {
                // 2. Check Verification Status
                try {
                    const { data: profile } = await supabase
